312	      headers: jsonHeaders,
313	    };
314	  }
315	
316	  // BigInt
317	  if (valType === "bigint") {
318	    return { body: val.toString(), headers: jsonHeaders };
319	  }
320	
321	  // Blob
322	  if (val instanceof Blob) {
323	    const headers = new Headers({
324	      "content-type": val.type,
325	      "content-length": val.size.toString(),
326	    });
327	
328	    // File
329	    let filename = (val as File).name;
330	    if (filename) {
331	      filename = encodeURIComponent(filename);
332	      // Omit the disposition type ("inline" or "attachment") and let the client (browser) decide.
333	      headers.set("content-disposition", `filename="${filename}"; filename*=UTF-8''${filename}`);
334	    }
335	
336	    return { body: val.stream(), headers };
337	  }
338	
339	  // Symbol or Function
340	  if (valType === "symbol") {
341	    return { body: val.toString() };
342	  }
343	  if (valType === "function") {
344	    return { body: `${(val as () => unknown).name}()` };
345	  }
346	
347	  return { body: val as BodyInit };
348	}
349	
350	function nullBody(method: string, status: number | undefined): boolean | 0 | undefined {
351	  // prettier-ignore
352	  return (method === "HEAD" ||
353	    status === 100 || status === 101 || status === 102 ||
354	    status === 204 || status === 205 || status === 304
355	  );
356	}
357	
358	function errorResponse(error: HTTPError, debug?: boolean, errHeaders?: Headers): Response {
359	  let headers: Headers = error.headers
360	    ? mergeHeaders(jsonHeaders, error.headers)
361	    : new Headers(jsonHeaders);
362	  if (errHeaders) {
363	    headers = mergeHeaders(headers, errHeaders);
364	  }
365	  return new FastResponse(
366	    JSON.stringify(
367	      {
368	        ...error.toJSON(),
369	        stack: debug && error.stack ? error.stack.split("\n").map((l) => l.trim()) : undefined,
370	      },
371	      undefined,
372	      debug ? 2 : undefined,
373	    ),
374	    {
375	      status: error.status,
376	      statusText: error.statusText,
377	      headers,
378	    },
379	  );
380	}
